fn derive_release_intent<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selection: &ReleaseSelection,
    source: SourceIdentity,
    trust_profile: ExecutionTrustProfileV1,
) -> Result<ReleaseIntentV1, GraphError> {
    let (snapshot, operations, _) = derive_release_inputs(workspace, selection, source)?;
    ReleaseIntentV1::new(snapshot, trust_profile, operations).map_err(|_error| GraphError::ReleaseIntentStale)
}

fn derive_release_intent_with_prepared<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selection: &ReleaseSelection,
    source: SourceIdentity,
    trust_profile: ExecutionTrustProfileV1,
) -> Result<(ReleaseIntentV1, BTreeMap<ReleaseOperationId, PreparedOperation>), GraphError> {
    let (snapshot, operations, prepared) = derive_release_inputs(workspace, selection, source)?;
    let intent =
        ReleaseIntentV1::new(snapshot, trust_profile, operations).map_err(|_error| GraphError::ReleaseIntentStale)?;
    Ok((intent, prepared))
}

fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selection: &ReleaseSelection,
    source: SourceIdentity,
) -> Result<
    (
        ReleaseInputSnapshotV1,
        Vec<ReleaseOperation>,
        BTreeMap<ReleaseOperationId, PreparedOperation>,
    ),
    GraphError,
> {
    let mut components = Vec::new();
    let mut kinds = BTreeSet::new();

    let mut selected = BTreeMap::new();
    let mut package_ids = BTreeMap::<callisto_model::PackageId, Vec<ReleasePackageId>>::new();
    for package in workspace.graph.packages() {
        for ecosystem in package
            .canonical_manifests()
            .map(|manifest| manifest.ecosystem())
            .collect::<BTreeSet<_>>()
        {
            let id =
                ReleasePackageId::new(ecosystem, package.id.name()).map_err(|_error| GraphError::ReleaseIntentStale)?;
            if let Some(version) = selection.versions().get(&id) {
                selected.insert(id.clone(), (package, version.clone()));
                package_ids.entry(package.id.clone()).or_default().push(id);
            }
        }
    }
    for id in selection.versions().keys() {
        if !selected.contains_key(id) {
            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
        }
    }

    let mut operations = BTreeMap::<ReleaseOperationId, ReleaseOperation>::new();
    let mut prepared = BTreeMap::<ReleaseOperationId, PreparedOperation>::new();
    let mut publishes_by_package = BTreeMap::<ReleasePackageId, Vec<ReleaseOperationId>>::new();
    let mut tag_by_package = BTreeMap::<ReleasePackageId, ReleaseOperationId>::new();

    // First construct leaves so dependency prerequisites can refer only to
    // exact selected release identities, never PackageId's wildcard matcher.
    for (id, (package, version)) in &selected {
        let fingerprint = package_fingerprint(workspace, id, package, version)?;
        push_fingerprint(&mut components, &mut kinds, format!("package:{id}"), fingerprint);

        let mut publishes = Vec::new();
        for target in &package.publish_to {
            if target.ecosystem() == Some(id.ecosystem()) {
                let registry_key = target.registry_key().expect("registry target has registry key");
                let binding = prepared_registry_binding(workspace, target)?;
                let operation = ReleaseOperation::registry_publish(
                    id.clone(),
                    version.clone(),
                    RegistryBindingId::new(registry_key.as_str(), binding.identity.clone())
                        .map_err(|_error| GraphError::ReleaseIntentStale)?,
                    Vec::new(),
                )
                .map_err(|_error| GraphError::ReleaseIntentStale)?;
                // A durable registry operation must have one exact endpoint
                // binding. The model-level operation identity currently has
                // only a registry key, so reject a second target that would
                // collapse to the same operation until the typed binding
                // identity is added there.
                if prepared.contains_key(operation.id()) {
                    return Err(GraphError::ReleaseIntentStale);
                }
                prepared.insert(
                    operation.id().clone(),
                    PreparedOperation::RegistryPublish {
                        package_dir: package_dir(package)?,
                        package_name: id.name().to_string(),
                        version: version.clone(),
                        registry: binding,
                        npm_access: match target {
                            PublishTarget::Npm { access, .. } => *access,
                            _ => None,
                        },
                    },
                );
                publishes.push(operation.id().clone());
                operations.insert(operation.id().clone(), operation);
            }
        }
        publishes.sort();
        publishes_by_package.insert(id.clone(), publishes);
    }

    // Replace each publish leaf with prerequisites from selected dependency
    // packages. This preserves the existing publish semantics: runtime,
    // build, optional, and dev dependencies must exist before publish.
    for (id, (package, _)) in &selected {
        let mut prerequisites = BTreeSet::new();
        for edge in workspace.graph.dependencies_of(&package.id) {
            if !matches!(
                edge.kind,
                DepKind::Runtime | DepKind::Build | DepKind::Optional | DepKind::Dev
            ) {
                continue;
            }
            for dependency_release_id in package_ids.get(&edge.to).into_iter().flatten() {
                prerequisites.extend(
                    publishes_by_package
                        .get(dependency_release_id)
                        .into_iter()
                        .flatten()
                        .cloned(),
                );
            }
        }
        for publish_id in publishes_by_package.get(id).into_iter().flatten() {
            let operation = operations.get(publish_id).expect("publish operation was constructed");
            let replacement = ReleaseOperation::new(operation.id().clone(), prerequisites.iter().cloned().collect())
                .map_err(|_error| GraphError::ReleaseIntentStale)?;
            operations.insert(publish_id.clone(), replacement);
        }
    }

    for (id, (package, version)) in &selected {
        if !package
            .publish_to
            .iter()
            .any(|target| !matches!(target, PublishTarget::None))
        {
            continue;
        }
        let tag = ReleaseOperation::tag(
            id.clone(),
            version.clone(),
            publishes_by_package.get(id).cloned().unwrap_or_default(),
        )
        .map_err(|_error| GraphError::ReleaseIntentStale)?;
        let tag_name = package
            .tag_template
            .clone()
            .unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))
            .render(version);
        let target = match &source {
            SourceIdentity::GitCommit { sha } => sha.clone(),
            SourceIdentity::HermeticContent { .. } => return Err(GraphError::ReleaseIntentStale),
        };
        prepared.insert(
            tag.id().clone(),
            PreparedOperation::Tag {
                annotation: format!("Release {tag_name}"),
                name: tag_name,
                target,
            },
        );
        tag_by_package.insert(id.clone(), tag.id().clone());
        operations.insert(tag.id().clone(), tag);
    }
    for (id, (package, version)) in &selected {
        if package
            .publish_to
            .iter()
            .any(|target| matches!(target, PublishTarget::GitHubRelease))
        {
            let tag = tag_by_package.get(id).expect("release point has tag").clone();
            let operation = ReleaseOperation::forge_release(id.clone(), version.clone(), vec![tag])
                .map_err(|_error| GraphError::ReleaseIntentStale)?;
            let tag = match prepared.get(operation.prerequisites().first().expect("forge release has tag")) {
                Some(PreparedOperation::Tag { name, .. }) => name.clone(),
                _ => return Err(GraphError::ReleaseIntentStale),
            };
            prepared.insert(operation.id().clone(), PreparedOperation::ForgeRelease { tag });
            operations.insert(operation.id().clone(), operation);
        }
    }

    Ok((
        ReleaseInputSnapshotV1::new(source, components),
        canonical_operation_order(operations)?,
        prepared,
//! Pure reconciliation of a durable release execution state.
//!
//! This is deliberately separate from the executor: it observes neither Git,
//! registries, nor a forge. Its only authority is one exact intent and the
//! state explicitly bound to that intent.

use std::collections::{BTreeMap, BTreeSet};

use callisto_model::{OperationState, ReleaseExecutionStateV1, ReleaseIntentV1, ReleaseOperationId};

use crate::GraphError;

/// The exact pending operations which are safe for a future executor to
/// consider. Being listed here does not perform an effect or bypass its
/// immediately-before-effect revalidation.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReconciledReleaseExecution {
    eligible: Vec<ReleaseOperationId>,
}

impl ReconciledReleaseExecution {
    /// Operations in the intent's stable canonical order.
    pub fn eligible(&self) -> &[ReleaseOperationId] {
        &self.eligible
    }
}

/// Reconciles `state` against exactly `intent` without performing any I/O.
///
/// An operation is eligible only while it is `Pending` and every *transitive*
/// prerequisite is exactly `Published` or `AlreadySatisfied`. `Attempting`,
/// missing, failed, and blocked operations are never inferred as success.
pub fn reconcile_release_execution(
    intent: &ReleaseIntentV1,
    state: &ReleaseExecutionStateV1,
) -> Result<ReconciledReleaseExecution, GraphError> {
    state
        .validate_for_intent(intent)
        .map_err(|source| GraphError::ReleaseExecutionState { source })?;

    let prerequisites: BTreeMap<_, _> = intent
        .operations
        .iter()
        .map(|operation| (operation.id().clone(), operation.prerequisites().to_vec()))
        .collect();

    let mut eligible = Vec::new();
    for operation in &intent.operations {
        if state.operation_state(operation.id()) != Some(OperationState::Pending) {
            continue;
        }
        let mut visited = BTreeSet::new();
        if prerequisites_satisfied_transitively(operation.id(), &prerequisites, state, &mut visited) {
            eligible.push(operation.id().clone());
        }
    }
    Ok(ReconciledReleaseExecution { eligible })
}

fn prerequisites_satisfied_transitively(
    id: &ReleaseOperationId,
    prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
    state: &ReleaseExecutionStateV1,
    visited: &mut BTreeSet<ReleaseOperationId>,
) -> bool {
    // `ReleaseIntentV1` has already proved this is a DAG. Keeping the visited
    // guard makes this helper fail closed if a future model version violates
    // that invariant rather than recursing indefinitely.
    if !visited.insert(id.clone()) {
        return false;
    }
    let result = prerequisites.get(id).is_some_and(|direct| {
        direct.iter().all(|prerequisite| {
            matches!(
                state.operation_state(prerequisite),
                Some(OperationState::Published | OperationState::AlreadySatisfied)
            ) && prerequisites_satisfied_transitively(prerequisite, prerequisites, state, visited)
        })
    });
    visited.remove(id);
    result
}

#[cfg(test)]
mod tests {
    use callisto_model::{
        Ecosystem, ExecutionTrustProfileV1, OperationBlockReason, OperationOutcome, ReleaseInputSnapshotV1,
        ReleaseOperation, ReleasePackageId, SourceIdentity, Version,
    };

    use super::*;

    fn intent() -> ReleaseIntentV1 {
        let package = ReleasePackageId::new(Ecosystem::Cargo, "demo").unwrap();
        let version = Version::semver(1, 0, 0);
        let publish = ReleaseOperation::registry_publish(package.clone(), version.clone(), "crates", vec![]).unwrap();
        let tag = ReleaseOperation::tag(package.clone(), version.clone(), vec![publish.id().clone()]).unwrap();
        let forge = ReleaseOperation::forge_release(package, version, vec![tag.id().clone()]).unwrap();
        ReleaseIntentV1::new(
            ReleaseInputSnapshotV1::new(SourceIdentity::git_commit("a".repeat(40)).unwrap(), vec![]),
            ExecutionTrustProfileV1::GitCommit,
            vec![publish, tag, forge],
        )
        .unwrap()
    }

    #[test]
    fn reconciliation_requires_transitive_exact_successes() {
        let intent = intent();
        let mut state = ReleaseExecutionStateV1::pending(&intent);
        let publish = intent.operations[0].id().clone();
        let tag = intent.operations[1].id().clone();
        let forge = intent.operations[2].id().clone();

        assert_eq!(
            reconcile_release_execution(&intent, &state).unwrap().eligible(),
            std::slice::from_ref(&publish)
        );
        state.mark_attempting(&publish).unwrap();
        state.mark_terminal(&publish, OperationOutcome::Published).unwrap();
        assert_eq!(
            reconcile_release_execution(&intent, &state).unwrap().eligible(),
            std::slice::from_ref(&tag)
        );
        state.mark_attempting(&tag).unwrap();
        state.mark_terminal(&tag, OperationOutcome::AlreadySatisfied).unwrap();
        assert_eq!(
            reconcile_release_execution(&intent, &state).unwrap().eligible(),
            &[forge]
        );
    }

    #[test]
    fn non_successful_or_attempting_prerequisites_never_make_dependents_eligible() {
        let intent = intent();
        let publish = intent.operations[0].id().clone();
        let tag = intent.operations[1].id().clone();
        let mut state = ReleaseExecutionStateV1::pending(&intent);
        state.mark_attempting(&publish).unwrap();
        assert!(reconcile_release_execution(&intent, &state)
            .unwrap()
            .eligible()
            .is_empty());
        state
            .mark_terminal(
                &publish,
                OperationOutcome::Blocked {
                    reason: OperationBlockReason::IndeterminateAttempt,
                },
            )
            .unwrap();
        assert!(reconcile_release_execution(&intent, &state)
            .unwrap()
            .eligible()
            .is_empty());
        assert_eq!(state.operation_state(&tag), Some(OperationState::Pending));
    }

    #[test]
    fn direct_success_cannot_hide_an_unsatisfied_transitive_prerequisite() {
        let intent = intent();
        let publish = intent.operations[0].id().clone();
        let tag = intent.operations[1].id().clone();
        let forge = intent.operations[2].id().clone();
        let mut state = ReleaseExecutionStateV1::pending(&intent);

        // The model state machine deliberately does not own DAG policy. This
        // represents a corrupted or legacy executor having recorded tag
        // success before its publish prerequisite. Reconciliation must still
        // fail closed for the forge operation.
        state.mark_attempting(&tag).unwrap();
        state.mark_terminal(&tag, OperationOutcome::Published).unwrap();
        assert_eq!(state.operation_state(&publish), Some(OperationState::Pending));
        let reconciled = reconcile_release_execution(&intent, &state).unwrap();
        assert_eq!(reconciled.eligible(), &[publish]);
        assert!(!reconciled.eligible().contains(&forge));
    }
}
//! Narrow, explicit-path persistence for durable release execution state.
//!
//! The store owns no release policy and does not derive paths from mutable
//! workspace configuration. Callers must supply the state path deliberately.

use std::path::{Path, PathBuf};

use callisto_model::{atomic::atomic_write, ApplyPermit, ReleaseExecutionStateV1, ReleaseIntentV1};

use crate::GraphError;

/// The only write seam used by [`ReleaseStateStore`]. Production writes use
/// Callisto's crash-safe atomic replacement primitive; tests can inject a
/// pre-rename failure without weakening that production path.
pub trait ReleaseStateWriter {
    fn write(&self, path: &Path, content: &str, permit: &ApplyPermit) -> std::io::Result<()>;
}

/// Production state writer backed by [`callisto_model::atomic::atomic_write`].
#[derive(Clone, Copy, Debug, Default)]
pub struct AtomicReleaseStateWriter;

impl ReleaseStateWriter for AtomicReleaseStateWriter {
    fn write(&self, path: &Path, content: &str, permit: &ApplyPermit) -> std::io::Result<()> {
        atomic_write(path, content, permit)
    }
}

/// Durable state store at one caller-chosen path.
#[derive(Debug)]
pub struct ReleaseStateStore<W = AtomicReleaseStateWriter> {
    path: PathBuf,
    writer: W,
}

impl ReleaseStateStore {
    /// Creates a production store at an explicit path.
    pub fn new(path: impl Into<PathBuf>) -> Self {
        Self::with_writer(path, AtomicReleaseStateWriter)
    }
}

impl<W> ReleaseStateStore<W>
where
    W: ReleaseStateWriter,
{
    /// Creates a store with a narrow writer seam, primarily for deterministic
    /// failure tests. The path remains explicit and is never config-derived.
    pub fn with_writer(path: impl Into<PathBuf>, writer: W) -> Self {
        Self {
            path: path.into(),
            writer,
        }
    }

    /// Returns the caller-chosen durable state location.
    pub fn path(&self) -> &Path {
        &self.path
    }

    /// Loads state if it exists and rejects any state not exactly bound to
    /// `intent`. A missing file is not evidence of a completed release.
    pub fn load(&self, intent: &ReleaseIntentV1) -> Result<Option<ReleaseExecutionStateV1>, GraphError> {
        let content = match std::fs::read_to_string(&self.path) {
            Ok(content) => content,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
            Err(error) => {
                return Err(GraphError::ReleaseStateRead {
                    path: self.path.clone(),
                    message: error.to_string(),
                });
            }
        };
        let state: ReleaseExecutionStateV1 =
            serde_json::from_str(&content).map_err(|error| GraphError::ReleaseStateDecode {
                path: self.path.clone(),
                message: error.to_string(),
            })?;
        state
            .validate_for_intent(intent)
            .map_err(|source| GraphError::ReleaseExecutionState { source })?;
        Ok(Some(state))
    }

    /// Loads existing state or atomically writes the exact pending roster.
    pub fn load_or_initialize(
        &self,
        intent: &ReleaseIntentV1,
        permit: &ApplyPermit,
    ) -> Result<ReleaseExecutionStateV1, GraphError> {
        if let Some(state) = self.load(intent)? {
            return Ok(state);
        }
        let state = ReleaseExecutionStateV1::pending(intent);
        self.save(intent, &state, permit)?;
        Ok(state)
    }

    /// Atomically persists only state proven to belong to `intent`.
    pub fn save(
        &self,
        intent: &ReleaseIntentV1,
        state: &ReleaseExecutionStateV1,
        permit: &ApplyPermit,
    ) -> Result<(), GraphError> {
        state
            .validate_for_intent(intent)
            .map_err(|source| GraphError::ReleaseExecutionState { source })?;
        let content = serde_json::to_string_pretty(state).expect("release state serialization is infallible") + "\n";
        self.writer
            .write(&self.path, &content, permit)
            .map_err(|error| GraphError::ReleaseStateWrite {
                path: self.path.clone(),
                message: error.to_string(),
            })
    }
}

